<?php
function e($value) { return htmlspecialchars((string) $value, ENT_QUOTES, 'UTF-8'); }
function pageStart($title, $active = '') { ?>
<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?= e($title) ?> · Unis pour aider</title><link rel="icon" href="images/logo.png"><link rel="stylesheet" href="css/style.css"></head><body>
<header class="site-header"><a class="brand" href="index.php" aria-label="Unis pour aider, accueil"><img src="images/logo.png" alt="Unis pour aider"></a><nav aria-label="Navigation principale"><?php foreach (['index.php'=>['Accueil','accueil'], 'actualites.php'=>['Actualités','actualites'], 'equipe.php'=>['L’équipe','equipe'], 'departement.php'=>['Départements','departement']] as $url=>$item): ?><a href="<?= $url ?>" <?= $active === $item[1] ? 'aria-current="page"' : '' ?>><?= $item[0] ?></a><?php endforeach; ?></nav><div class="header-actions"><a class="contact-link" href="contact.php">Nous contacter</a><?php if (isset($_SESSION['user_id'])): ?><a class="account-link" href="profil.php">Mon profil</a><form method="post"><button class="logout" name="disconnect">Déconnexion</button></form><?php else: ?><a class="account-link" href="login.php">Espace membre</a><?php endif; ?></div></header><main id="main">
<?php }
function pageEnd() { ?>
</main><footer class="site-footer"><div><a class="footer-title" href="index.php">Unis pour aider<span>.</span></a><p>Association de solidarité à Liège.</p></div><div><span class="eyebrow">Retrouvons-nous</span><p>Rue de Harlez 25, Liège</p><a href="contact.php">Prendre contact</a></div><div class="footer-note">Projet scolaire · Démonstration portfolio<br>Solidarité. Proximité. Engagement.</div></footer></body></html>
<?php }
function heading($tag,$title,$text) { ?><div class="page-heading"><h1><?= e($title) ?></h1><p><?= e($text) ?></p></div><?php }
function notice($message) { if ($message): ?><p class="notice" role="status"><?= e(strip_tags($message)) ?></p><?php endif; }
function newsCard($item) { ?><article class="news-card"><div class="news-top"><span class="pill">Vie de l’association</span><time datetime="<?= e($item->date_actualite) ?>"><?= date('d.m.Y', strtotime($item->date_actualite)) ?></time></div><h3><?= e(html_entity_decode($item->intitule, ENT_QUOTES, 'UTF-8')) ?></h3><p><?= e(html_entity_decode($item->actualite, ENT_QUOTES, 'UTF-8')) ?></p><div class="news-bottom"><span>Unis pour aider</span></div></article><?php }
function memberCard($member) { ?><li class="member-card"><div class="portrait"><img loading="lazy" src="<?= e($member->photo) ?>" alt="<?= e($member->prenom . ' ' . $member->nom) ?>"></div><div class="member-info"><h3><?= e($member->prenom . ' ' . $member->nom) ?></h3><p><?= e($member->description ?: 'Membre de l’association') ?></p></div></li><?php }
